// Your new Node.js app. FloServer runs `npm start` and passes the port in PORT.
const http = require('node:http');

const port = Number(process.env.PORT) || 3000;

http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`<!doctype html><title>Node app</title>
<body style="font-family: system-ui, sans-serif; margin: 3rem">
<h1>Node app</h1><p>Running on Node.js ${process.version}. Edit <code>server.js</code> to start.</p>`);
}).listen(port, '127.0.0.1');
